mapper.select:
SELECT

FROM customer c
WHERE c.deleted = FALSE


    AND c.seller_id IN
    #{scopeId}


    AND FALSE



    AND (c.customer_code ILIKE CONCAT('%', #{query.keyword}, '%')
    OR c.name ILIKE CONCAT('%', #{query.keyword}, '%')
    OR c.contact_name ILIKE CONCAT('%', #{query.keyword}, '%')
    OR c.contact_phone ILIKE CONCAT('%', #{query.keyword}, '%'))


    AND c.customer_type_id = #{query.customerTypeId}


    AND c.status = #{query.status}


    AND c.settle_mode = #{query.settleMode}


    AND c.parent_customer_id = #{query.parentCustomerId}

mapper.update:
UPDATE customer
SET deleted    = TRUE,
    version    = version + 1,
    updated_at = CURRENT_TIMESTAMP,
    updated_by = #{operator}
WHERE id = #{customerId}
  AND version = #{version}
  AND deleted = FALSE
